Client Minimap Overlay.Code:
function drawTerritories(){
 loadedChunks.forEach((chunk,key)=>{
  const faction = chunk.faction;
  if(!faction) return;

  const color = faction.color || 'purple';
  mctx.fillStyle = color;
  mctx.globalAlpha = 0.3;
  mctx.fillRect(100 + chunk.x*5, 100 + chunk.y*5, 5, 5);
  mctx.globalAlpha = 1;
 });
}

